mapper.select:
SELECT s.id, s.spot_name AS name, s.province, s.city, s.address, s.latitude, s.longitude, s.altitude, s.light_pollution_level AS bortleLevel, s.rating, s.rating_count AS ratingCount, s.description, s.create_time AS createTime, /* mainImage: 从 images JSON 里取第一张，找不到返回 null */ CASE WHEN s.images IS NULL OR s.images = '[]' OR s.images = '' THEN NULL ELSE JSON_UNQUOTE(JSON_EXTRACT(s.images, '$[0]')) END AS mainImage, /* Haversine 距离公式，单位 km，保留2位小数 */ ROUND( 2 * 6371 * ASIN( SQRT( POWER(SIN((s.latitude - #{latitude}) * PI() / 360), 2) + COS(#{latitude} * PI() / 180) * COS(s.latitude * PI() / 180) * POWER(SIN((s.longitude - #{longitude}) * PI() / 360), 2) ) ), 2 ) AS distance, /* 当前用户评分（未登录或未评分返回 NULL） */
(SELECT r.score FROM tb_spot_rating r WHERE r.user_id = #{currentUserId} AND r.spot_id = s.id LIMIT 1)
NULL
AS myScore FROM tb_observation_spot s WHERE s.deleted = 0
AND s.province = #{province}
AND s.city = #{city}
AND s.light_pollution_level <= #{maxLightPollution}
HAVING distance <= #{radius} ORDER BY distance ASC LIMIT #{limit}
